    when(prepStmt.executeQuery()).thenReturn(results);
    when(conn.createStatement()).thenReturn(stmt);
    when(stmt.executeQuery(any(String.class))).thenReturn(results);
    when(conn.prepareCall(any(String.class))).thenReturn(call);
